import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CeYlivdO.js";const u=JSON.parse('{"title":"跨线程安全、性能取舍与设计原则总结","description":"生命周期安全不等于线程安全——指针语义设计的最终工程规则与推荐命名","frontmatter":{"title":"跨线程安全、性能取舍与设计原则总结","description":"生命周期安全不等于线程安全——指针语义设计的最终工程规则与推荐命名","chapter":1,"order":6,"tags":["host","cpp-modern","intermediate","智能指针","内存管理"],"difficulty":"intermediate","platform":"host","reading_time_minutes":7,"prerequisites":["std::weak_ptr 对比与异步回调实战"],"related":["卷二 · 第一章：智能指针与 RAII"],"cpp_standard":[17,20]},"headers":[],"relativePath":"vol8-domains/cpp-deep-dives/pointer-semantics/06-design-principles.md","filePath":"vol8-domains/cpp-deep-dives/pointer-semantics/06-design-principles.md","lastUpdated":null}'),a={name:"vol8-domains/cpp-deep-dives/pointer-semantics/06-design-principles.md"};function c(s,e,n,l,p,i){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="跨线程安全、性能取舍与设计原则总结" tabindex="-1">跨线程安全、性能取舍与设计原则总结 <a class="header-anchor" href="#跨线程安全、性能取舍与设计原则总结" aria-label="Permalink to &quot;跨线程安全、性能取舍与设计原则总结&quot;">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>到这里，我们已经把非拥有指针的整个光谱走了一遍——从最简单的 <code>T*</code> 和 <code>T&amp;</code>，到手搓的 <code>Borrowed&lt;T&gt;</code> 和 <code>ObserverPtr&lt;T&gt;</code>，再到三种弱引用方案（<code>UnsafeWeakPtr</code>、<code>SimpleWeakPtr</code>、Chrome-like <code>WeakPtr</code>），最后和 <code>std::weak_ptr</code> 做了全面对比。</p><p>这一篇是收尾，我们把三个还没彻底展开的话题说清楚：跨线程安全的边界到底在哪里，各种类型的性能开销具体差多少，以及把所有东西综合成一组可以落地的工程规则。</p><h2 id="生命周期安全-线程安全" tabindex="-1">生命周期安全 ≠ 线程安全 <a class="header-anchor" href="#生命周期安全-线程安全" aria-label="Permalink to &quot;生命周期安全 ≠ 线程安全&quot;">​</a></h2><p>这是整个专题最重要的一个结论，值得反复强调。</p><p><strong>生命周期安全</strong>说的是&quot;对象销毁后你能不能安全地检测到失效&quot;。<code>WeakPtr</code> 的 control block 解决的就是这个问题——你可以安全地调用 <code>is_valid()</code> 或 <code>get()</code> 而不会 UB。</p><p><strong>线程安全</strong>说的是&quot;多个线程同时访问对象时会不会出问题&quot;。这和生命周期安全是完全不同的问题维度。</p><p>我们用一张 2×2 的表格来把这四个象限说清楚：</p><table tabindex="0"><thead><tr><th></th><th>生命周期不安全</th><th>生命周期安全</th></tr></thead><tbody><tr><td><strong>线程不安全</strong></td><td><code>T*</code>、<code>T&amp;</code>、<code>ObserverPtr</code></td><td>Chrome <code>WeakPtr</code>（单 sequence）</td></tr><tr><td><strong>线程安全（部分）</strong></td><td>N/A（没有意义）</td><td><code>std::weak_ptr</code>（lock 原子，但 T 的内部状态需要同步）</td></tr></tbody></table><p><code>T*</code> 在左上角——既不解决生命周期问题，也不解决线程问题。Chrome <code>WeakPtr</code> 解决了生命周期问题，但在跨线程场景下仍然有 TOCTOU 竞态。<code>std::weak_ptr</code> 的 <code>lock()</code> 是原子的，锁住之后对象不会被析构，但对象<strong>内部状态</strong>的并发访问仍然需要 mutex 或其他机制保护。</p><p>所以：<code>WeakPtr</code> 解决的是&quot;我知道对象死了没有&quot;，不是&quot;多个线程同时碰这个对象安不安全&quot;。</p><h3 id="为什么-chrome-weakptr-是-sequence-bound-的" tabindex="-1">为什么 Chrome WeakPtr 是 sequence-bound 的 <a class="header-anchor" href="#为什么-chrome-weakptr-是-sequence-bound-的" aria-label="Permalink to &quot;为什么 Chrome WeakPtr 是 sequence-bound 的&quot;">​</a></h3><p>Chrome 的设计哲学是：大多数 UI 和异步框架中的回调都跑在同一个逻辑序列上。定时器回调、事件处理、IO 完成通知——它们由同一个 task runner 分发执行。在这个模型下，invalidate 和 get 不可能同时执行，因为它们排队运行。</p><p>这比&quot;加一个 mutex 就跨线程安全了&quot;要高效得多——mutex 有运行时开销，而 sequence-bound 是零开销的设计约束。代价是你的使用方式被限制了：不能跨 sequence 传递 WeakPtr。但这个约束在大多数 UI / 事件循环框架里是自然成立的。</p><h3 id="跨线程场景应该怎么做" tabindex="-1">跨线程场景应该怎么做 <a class="header-anchor" href="#跨线程场景应该怎么做" aria-label="Permalink to &quot;跨线程场景应该怎么做&quot;">​</a></h3><p>如果确实需要跨线程弱引用，有几种选择：</p><ul><li><strong>用 <code>std::weak_ptr</code></strong>：<code>lock()</code> 原子地获取 <code>shared_ptr</code>，在你的作用域内对象不会被析构。但 T 内部的线程安全需要另外处理。</li><li><strong>用 <code>std::atomic&lt;std::shared_ptr&lt;T&gt;&gt;</code></strong>（C++20）：提供原子操作来安全地跨线程读写 <code>shared_ptr</code>。</li><li><strong>用 message passing</strong>：不直接跨线程共享 WeakPtr，而是通过消息队列传递&quot;请你在你的 sequence 上做这件事&quot;的请求，让目标 sequence 自己处理。</li></ul><h2 id="性能比较" tabindex="-1">性能比较 <a class="header-anchor" href="#性能比较" aria-label="Permalink to &quot;性能比较&quot;">​</a></h2><p>我们把本专题涉及的所有类型做一个性能对比。数字是近似值，具体取决于平台和编译器：</p><table tabindex="0"><thead><tr><th>类型</th><th>对象大小</th><th>控制块分配</th><th>原子操作</th><th>适合</th></tr></thead><tbody><tr><td><code>T*</code></td><td>8B</td><td>无</td><td>无</td><td>同步函数参数</td></tr><tr><td><code>T&amp;</code></td><td>8B（指针实现）</td><td>无</td><td>无</td><td>同步函数参数</td></tr><tr><td><code>Borrowed&lt;T&gt;</code></td><td>8B</td><td>无</td><td>无</td><td>同步函数参数（语义显式）</td></tr><tr><td><code>ObserverPtr&lt;T&gt;</code></td><td>8B</td><td>无</td><td>无</td><td>类成员观察</td></tr><tr><td><code>UnsafeWeakPtr&lt;T&gt;</code></td><td>16B</td><td>无</td><td>无</td><td>不应该使用</td></tr><tr><td><code>SimpleWeakPtr&lt;T&gt;</code></td><td>24B（T* + shared_ptr）</td><td>1 次 <code>new</code></td><td>拷贝 1 次、析构 1~2 次原子操作</td><td>教学、简单场景</td></tr><tr><td>Chrome <code>WeakPtr&lt;T&gt;</code></td><td>16B（<code>T*</code> + <code>WeakFlag*</code>）</td><td>1 次 <code>new</code></td><td>拷贝/析构各 1 次原子操作</td><td>框架内异步回调</td></tr><tr><td><code>std::weak_ptr&lt;T&gt;</code></td><td>16B</td><td>由 <code>shared_ptr</code> 管理</td><td>lock/unlock 各 2 次原子操作</td><td>shared_ptr 体系</td></tr></tbody></table><p>几个值得注意的细节：</p><p><code>Borrowed&lt;T&gt;</code> 和 <code>ObserverPtr&lt;T&gt;</code> 的开销为零——编译器优化后和裸指针完全一样。它们的价值纯粹在语义层面。</p><p><code>SimpleWeakPtr&lt;T&gt;</code> 比 Chrome <code>WeakPtr&lt;T&gt;</code> 大了 8 个字节，因为 <code>shared_ptr</code> 内部有两个指针（对象指针 + 控制块指针），而 Chrome 的 <code>WeakPtr</code> 只存 <code>T*</code> 和 <code>WeakFlag*</code>。每次拷贝 <code>shared_ptr</code> 需要两次原子操作（strong count + weak count），Chrome 只需要一次。</p><p>Chrome <code>WeakPtr</code> 的控制块（<code>WeakFlag</code>）比 <code>shared_ptr</code> 的控制块小得多——只有一个原子 bool 和一个原子 int，没有虚析构、没有 allocator、没有 weak count。</p><p><code>std::weak_ptr</code> 的额外开销取决于它所依赖的 <code>shared_ptr</code>。如果你为了用 <code>weak_ptr</code> 而把一个本来不需要 <code>shared_ptr</code> 的对象强行改成 <code>shared_ptr</code> 管理，你不仅要付出控制块的开销，还引入了原子引用计数争用的风险。</p><h2 id="工程规则" tabindex="-1">工程规则 <a class="header-anchor" href="#工程规则" aria-label="Permalink to &quot;工程规则&quot;">​</a></h2><p>总结成一组可落地的规则：</p><p><strong>函数参数</strong>优先用 <code>T&amp;</code>、<code>T*</code> 或 <code>Borrowed&lt;T&gt;</code>。不要在函数参数上使用智能指针来表达非拥有关系。<code>Borrowed&lt;T&gt;</code> 提供最明确的语义（非空 + 非拥有），但 <code>const T&amp;</code> 在大多数场景下也够用。</p><p><strong>类成员观察关系</strong>可以用 <code>ObserverPtr&lt;T&gt;</code>。当你要表达&quot;我观察它但不拥有它&quot;时，<code>ObserverPtr&lt;T&gt;</code> 比裸 <code>T*</code> 的可读性好得多。但要记住它不能判活。</p><p><strong>异步回调</strong>永远不要捕获裸 <code>this</code>、裸 <code>T*</code>、<code>ObserverPtr</code> 或任何没有独立 control block 的&quot;弱引用&quot;。正确的选择是 Chrome-like <code>WeakPtr&lt;T&gt;</code>（非 <code>shared_ptr</code> 场景）或 <code>std::weak_ptr&lt;T&gt;</code>（<code>shared_ptr</code> 场景）。</p><p><strong>不要把 <code>ObserverPtr</code> 当 WeakPtr 用</strong>。<code>ObserverPtr</code> 只能表达&quot;我不拥有它&quot;，不能表达&quot;我知道它还活着吗&quot;。</p><p><strong>不要把 <code>T* + raw Flag*</code> 叫 WeakPtr</strong>。如果 Flag 的生命周期绑定在 Owner 上，它不是可靠 WeakPtr。给它一个诚实的名字——<code>UnsafeWeakPtr</code> 或 <code>OwnerBoundWeakPtr</code>。</p><p><strong>跨线程场景</strong>优先考虑 <code>std::weak_ptr&lt;T&gt;</code> 或 message passing。Chrome-like <code>WeakPtr</code> 设计上是 sequence-bound 的，不要把它当跨线程安全指针用。</p><p><strong>WeakPtr 解决生命周期感知，不解决线程安全</strong>。无论用哪种 WeakPtr，T 内部状态的并发访问都需要额外的同步机制。</p><h2 id="推荐命名体系" tabindex="-1">推荐命名体系 <a class="header-anchor" href="#推荐命名体系" aria-label="Permalink to &quot;推荐命名体系&quot;">​</a></h2><p>最后给出一套推荐的命名约定：</p><table tabindex="0"><thead><tr><th>类型</th><th>命名</th><th>含义</th></tr></thead><tbody><tr><td><code>Borrowed&lt;T&gt;</code></td><td>借用</td><td>非空、非拥有、短期使用、适合函数参数</td></tr><tr><td><code>ObserverPtr&lt;T&gt;</code></td><td>观察</td><td>可空、非拥有、不提供判活、适合类成员</td></tr><tr><td><code>UnsafeWeakPtr&lt;T&gt;</code></td><td>不安全弱引用</td><td><code>T*</code> + <code>raw Flag*</code>，命名明确标注不安全</td></tr><tr><td><code>WeakPtr&lt;T&gt;</code></td><td>安全弱引用</td><td>真正能在对象销毁后安全判空的弱引用</td></tr><tr><td><code>WeakPtrFactory&lt;T&gt;</code></td><td>弱引用工厂</td><td>集中创建和管理 WeakPtr 的失效</td></tr></tbody></table><p><code>UnsafeWeakPtr</code> 这个名字不是贬义——它是一种<strong>诚实的命名</strong>。当你在代码库里看到 <code>UnsafeWeakPtr</code>，你立刻就知道&quot;这个东西有坑，使用时要注意约束条件&quot;。比把它包装成 <code>WeakPtr</code> 然后在文档里埋一行小字说&quot;保证 WeakPtr 不比 Owner 长&quot;要负责任得多。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生命周期安全和线程安全是两个正交的问题，WeakPtr 只解决前者</li><li>Chrome <code>WeakPtr</code> 通过 sequence-bound 模型获得零开销的安全性，但限制跨线程使用</li><li><code>Borrowed</code> 和 <code>ObserverPtr</code> 运行时开销为零，价值在语义表达</li><li>Chrome <code>WeakPtr</code> 的控制块比 <code>shared_ptr</code> 的控制块更轻量</li><li>不要为了用 <code>weak_ptr</code> 而强行引入 <code>shared_ptr</code></li><li>命名应该诚实——不安全的东西就要叫不安全</li></ul><p>这个专题到这里就全部结束了。我们从 <code>T*</code> 出发，手搓了 Borrowed、ObserverPtr、UnsafeWeakPtr、SimpleWeakPtr 和 Chrome-like WeakPtr，每一步都解释了设计理由和工程取舍。希望这些内容能帮你在实际工程中做出更清晰的指针语义选择。</p><h2 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h2><ul><li><a href="https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines" target="_blank" rel="noreferrer">C++ Core Guidelines</a></li><li><a href="https://www.chromium.org/developers/smart-pointer-guidelines/" target="_blank" rel="noreferrer">Chromium Smart Pointer Guidelines</a></li><li><a href="https://en.cppreference.com/w/cpp/memory/weak_ptr" target="_blank" rel="noreferrer">std::weak_ptr - cppreference</a></li><li><a href="https://github.com/microsoft/GSL" target="_blank" rel="noreferrer">GSL: Guidelines Support Library</a></li><li><a href="https://www.open-std.org/jtc1/sc22/wg21/docs/papers/2019/p1408r0.pdf" target="_blank" rel="noreferrer">P1408R0: Abandon observer_ptr (Stroustrup)</a></li></ul>',44)])])}const k=t(a,[["render",c]]);export{u as __pageData,k as default};
